_all_decided(results) := [p | some r in results; some p in _decided(r)]

_first_decided(results, status) := _decided(firsts[0]) if {
	firsts := [r | some r in results; r.status == status]
}

all_of(results) := {"status": "false", "predicates": _predicates(results), "decided": _first_decided(results, "false")} if {
	some r in results
	r.status == "false"
} else := {"status": "unknown", "unknown": unknown, "predicates": _predicates(results)} if {
	unknown := _first_unknown_result(results)
} else := {"status": "true", "predicates": _predicates(results), "decided": _all_decided(results)}

any_of(results) := {"status": "true", "predicates": _predicates(results), "decided": _first_decided(results, "true")} if {
	some r in results
	r.status == "true"
} else := {"status": "unknown", "unknown": unknown, "predicates": _predicates(results)} if {
	unknown := _first_unknown_result(results)
} else := {"status": "false", "predicates": _predicates(results), "decided": _all_decided(results)}

# A negation flips its result. The predicates that decided it are marked as negated
# (twice negated is not negated), so a reason can say one held where it must not.
_flip(value) := false if {
	value
} else := true

_negated(predicates) := [object.union(p, {"negated": _flip(object.get(p, "negated", false))}) | some p in predicates]

not_of(result) := {"status": "false", "predicates": result.predicates, "decided": _negated(_decided(result))} if {
	result.status == "true"
} else := {"status": "true", "predicates": result.predicates, "decided": _negated(_decided(result))} if {
	result.status == "false"
} else := result

# The elements of a collection lookup, or none when it is unknown or not a list.
# (A set never occurs in JSON input; the branch above keeps `_summary` total.)
elements(collection) := collection.value if {
	collection.known
	is_array(collection.value)
} else := []

_exists_obs(collection, status, matched) := {
	"path": collection.path,
	"op": "exists",
	"expected": null,
	"actual": actual,
	"status": status,
	"matched": matched,
} if {
	collection.known
	actual := _summary(collection.value)
} else := {"path": collection.path, "op": "exists", "expected": null, "actual": null, "status": status, "matched": matched}

exists_of(collection, results) := {"status": "unknown", "unknown": unknown, "predicates": [obs]} if {
	not collection.known
	unknown := {"path": collection.path, "reason": collection.reason}
	obs := _exists_obs(collection, "unknown", null)
} else := {"status": "unknown", "unknown": unknown, "predicates": [obs]} if {
	not is_array(collection.value)
	unknown := {"path": collection.path, "reason": "not_a_list"}
	obs := _exists_obs(collection, "unknown", null)
} else := {"status": "true", "predicates": [obs], "decided": [obs]} if {
	matched := count([r | some r in results; r.status == "true"])
	matched > 0
	obs := _exists_obs(collection, "true", matched)
} else := {"status": "unknown", "unknown": unknown, "predicates": [obs]} if {
	unknown := _first_unknown_result(results)
	obs := _exists_obs(collection, "unknown", 0)
} else := {"status": "false", "predicates": [obs], "decided": [obs]} if {
	obs := _exists_obs(collection, "false", 0)
}

# One result for the subject the input describes.
_status_of_check := "pass" if {
	_check.status == "true"
} else := "fail" if {
	_check.status == "false"
} else := "unknown"

status := "not_applicable" if {
	_guard.status == "false"
} else := "unknown" if {
	_guard.status == "unknown"
} else := _status_of_check

_unknown := object.get(_guard, "unknown", null) if {
	_guard.status == "unknown"
} else := object.get(_check, "unknown", null) if {
	_guard.status == "true"
	_check.status == "unknown"
} else := null

# Every predicate observation, tagged with the clause it belongs to and its
# position, so a reason can name one unambiguously.
_clause(result, clause) := [object.union(p, {"clause": clause}) | some p in result.predicates]

_observed := [object.union(p, {"index": i}) |
	some i, p in array.concat(_clause(_guard, "when"), _clause(_check, "assert"))
]

reason := "when: false" if {
	status == "not_applicable"
} else := sprintf("%s: %s", [_unknown.path, _unknown.reason]) if {
	status == "unknown"
} else := "assert: true" if {
	status == "pass"
} else := sprintf("assert: false; %s %s is true, but must be false", [last.path, last.op]) if {
	# Under a negation every part that held decided it; the last one usually states
	# the condition, the ones before it narrow down what it is about.
	decided := _decided(_check)
	object.get(decided[0], "negated", false)
	last := decided[count(decided) - 1]
} else := sprintf("assert: false; %s %s is false", [first.path, first.op]) if {
	first := _decided(_check)[0]
} else := "assert: false"

_when_status := _guard.status if {
	_has_when
} else := null

observations := {
	"when": _when_status,
	"predicates": _observed,
	"unknown": _unknown,
}

# The subject is echoed as its kind and key only, bounded like every observed value.
_subject := {"kind": _summary(object.get(subject, "kind", null)), "key": _summary(object.get(subject, "key", null))} if {
	is_object(input)
	subject := input.subject
	is_object(subject)
} else := null

evaluate := [{
	"subject": _subject,
	"status": status,
	"reason": reason,
	"observations": observations,
}]
